            String nDef = rDefault.getClass().getSimpleName();
            String nSame = rSame.getClass().getSimpleName();
            String nLarger = rLarger.getClass().getSimpleName();
            String nSmaller = rSmaller.getClass().getSimpleName();
            String nMuch = rMuchSmaller.getClass().getSimpleName();

            assert "ProgressiveBilinearResizer".equals(nDef) : "Expected ProgressiveBilinearResizer, got " + nDef;
            assert "NullResizer".equals(nSame) : "Expected NullResizer, got " + nSame;
