            assert "BilinearResizer".equals(nSmaller) : "Expected BilinearResizer, got " + nSmaller;
            assert "ProgressiveBilinearResizer".equals(nMuch) : "Expected ProgressiveBilinearResizer, got " + nMuch;

            System.out.println("__CHECK__ getResizer " + nDef + "," + nSame + "," + nLarger + "," + nSmaller + "," + nMuch);
